const ACUP_FIND={"足三里": "屈膝，用同侧手掌心按住膝盖骨，中指指尖所指处（胫骨外侧一横指）即是。", "涌泉": "蜷足时足底前1/3出现的凹窝即是，约在第2、3趾趾缝纹头与足跟连线的前1/3处。", "合谷": "一手拇指指关节横纹对准另一手虎口边缘，拇指尖按到处；或拇、食指并拢，虎口肌肉隆起最高处。", "百会": "两耳尖连线与头正中线的交点，头顶正中凹陷处。", "关元": "仰卧，以肚脐为起点向下量本人四指并拢（约3寸），前正中线上即是。", "气海": "仰卧，肚脐正下方约两横指（1.5寸），前正中线上。", "内关": "手掌心向上，腕横纹往上约三指宽，两根筋中间。", "三阴交": "内踝尖往上约四横指（3寸），胫骨内侧缘后方，按压有酸胀感处。", "委中": "膝盖后面腘窝横纹的正中点，屈膝时两条大筋之间。", "列缺": "两手虎口交叉，一手食指按在另一手腕部高骨（桡骨茎突）上，指尖尽处凹陷。", "风池": "后颈枕骨下，两条大筋之间的凹陷处，与耳垂大致相平。", "太冲": "足背第1、2趾之间，从趾缝往上约两横指，可摸到动脉跳动的凹陷处。", "脾俞": "先摸到肩胛骨下角（约第7胸椎），往下数4个棘突，再旁开约两横指。", "肺俞": "低头时颈后最高骨（第7颈椎）往下数3个棘突，旁开约两横指。", "膻中": "两乳头连线与胸骨正中线的交点，胸骨按压有酸胀处。", "中脘": "胸骨下端（剑突）与肚脐连线的中点，前正中线上。", "命门": "后腰正中，与肚脐正相对的脊柱棘突下凹陷（约第2腰椎）。", "肾俞": "后腰与肚脐相平处，脊柱旁开约两横指。", "大椎": "低头时颈后摸到最高最突出的骨头（第7颈椎），其下方凹陷处。", "神阙": "以肚脐为唯一标志，即脐窝正中央（此穴禁针，只宜摩腹）。", "太溪": "内踝尖与跟腱之间的凹陷，按之有酸胀感。", "复溜": "先取太溪，再直上约三横指（2寸），跟腱前缘。", "照海": "内踝尖正下方，内踝下缘与距骨之间的凹陷处。", "丰隆": "外踝尖上约八横指（8寸），胫骨前肌外缘，条口穴旁开一横指。", "阴陵泉": "小腿内侧，沿胫骨内侧缘自下而上推，至胫骨内侧髁下缘的凹陷处。", "曲池": "屈肘成直角，肘横纹外侧尽头与肱骨外上髁连线的中点。", "血海": "屈膝，膝盖骨内上角往上约两横指，大腿内侧肌肉隆起处。", "膈俞": "后背第7胸椎棘突下旁开两横指，约与肩胛骨下角相平。", "期门": "乳头直下，第6肋间隙，约胸骨下端与肚脐连线中点旁开四寸。", "神门": "手腕掌侧横纹靠小指一侧，尺侧腕屈肌腱内侧的凹陷处。", "迎香": "鼻翼外缘中点旁，鼻唇沟（法令纹）中。", "风门": "低头时颈后最高骨往下数2个棘突（第2胸椎），旁开约两横指。"};
const ACUP_SIDE={"足三里": {"t": "左小腿", "x": 39.1, "y": 50.8}, "涌泉": {"t": "左足底", "x": 45.6, "y": 38.8}, "合谷": {"t": "左手背", "x": 39.4, "y": 36.2}, "百会": {"t": "头顶正中", "x": 42.8, "y": 45.8}, "关元": {"t": "下腹正中", "x": 40.0, "y": 52.5}, "气海": {"t": "下腹正中", "x": 48.4, "y": 33.3}, "内关": {"t": "右前臂", "x": 58.8, "y": 34.6}, "三阴交": {"t": "右小腿", "x": 58.4, "y": 55.8}, "委中": {"t": "右膝后", "x": 53.1, "y": 55.4}, "列缺": {"t": "右前臂", "x": 61.3, "y": 45.4}, "风池": {"t": "右颈后", "x": 56.2, "y": 45.0}, "太冲": {"t": "右足背", "x": 57.8, "y": 45.8}, "脾俞": {"t": "左背部", "x": 40.9, "y": 49.2}, "肺俞": {"t": "右背部", "x": 53.4, "y": 57.5}, "膻中": {"t": "前胸正中", "x": 39.7, "y": 55.4}, "中脘": {"t": "上腹正中", "x": 43.4, "y": 57.1}, "命门": {"t": "后腰正中", "x": 42.2, "y": 48.3}, "肾俞": {"t": "左腰部", "x": 40.3, "y": 60.0}, "大椎": {"t": "颈后正中", "x": 59.4, "y": 57.5}, "神阙": {"t": "脐部正中", "x": 37.8, "y": 61.3}, "太溪": {"t": "左踝部", "x": 43.4, "y": 55.0}, "复溜": {"t": "右小腿", "x": 50.3, "y": 37.9}, "照海": {"t": "右踝部", "x": 53.4, "y": 64.6}, "丰隆": {"t": "左小腿", "x": 40.0, "y": 52.5}, "阴陵泉": {"t": "右小腿", "x": 54.4, "y": 39.2}, "曲池": {"t": "右肘部", "x": 50.6, "y": 44.6}, "血海": {"t": "左大腿", "x": 38.4, "y": 37.9}, "膈俞": {"t": "右背部", "x": 58.8, "y": 55.8}, "期门": {"t": "左胸胁", "x": 38.4, "y": 47.1}, "神门": {"t": "左腕部", "x": 48.1, "y": 56.7}, "迎香": {"t": "右面部", "x": 58.4, "y": 60.0}, "风门": {"t": "左背部", "x": 48.8, "y": 47.5}};
const READ_ADD={"黄帝内经": [{"t": "素问 · 四气调神大论（夏三月）", "s": "夏三月，此谓蕃秀。天地气交，万物华实。夜卧早起，无厌于日，使志无怒。", "tr": "夏季的三个月，是草木繁茂、开花孕果的时节。天地阴阳之气相交，万物开花结实。应当晚睡早起，不要嫌恶日光，让心志保持平和不动怒。"}, {"t": "素问 · 四气调神大论（秋三月）", "s": "秋三月，此谓容平。天气以急，地气以明。早卧早起，与鸡俱兴，使志安宁。", "tr": "秋季的三个月，是万物形态安定、成熟平定的时节。天风劲急，地气清肃明朗。应当早睡早起，作息与鸡的起止相合，让心志安宁不躁。"}, {"t": "素问 · 四气调神大论（冬三月）", "s": "冬三月，此谓闭藏。水冰地坼，无扰乎阳。早卧晚起，必待日光。", "tr": "冬季的三个月，是万物封藏的时节。水面结冰，大地冻裂，此时不要扰动阳气。应当早睡晚起，一定要等到日出后再活动。"}, {"t": "素问 · 阴阳应象大论", "s": "阴阳者，天地之道也，万物之纲纪，变化之父母，生杀之本始，神明之府也。治病必求于本。", "tr": "阴阳是天地运行的根本规律，是统摄万物的纲领，是变化的源头、生长与消亡的起始，也是自然神妙变化之所在。诊治疾病，一定要推求这个根本。"}, {"t": "灵枢 · 本神", "s": "故智者之养生也，必顺四时而适寒暑，和喜怒而安居处，节阴阳而调刚柔。", "tr": "所以懂养生的人，必定顺应四时、适应寒暑变化，调和情绪、安于起居，调节阴阳、使刚柔得宜，如此才能长久安康。"}], "神农本草经": [{"t": "序录 · 三品分类", "s": "上药一百二十种为君，主养命以应天，无毒，多服久服不伤人。中药一百二十种为臣，主养性以应人。下药一百二十五种为佐使，主治病以应地，多毒，不可久服。", "tr": "全书把药物分作三品：上品一百二十种为君，用以养命、顺应天道，无毒，长期服用不伤人；中品一百二十种为臣，用以调养性情、顺应人事；下品一百二十五种为佐使，用以治病，多有毒性，不可久服。"}, {"t": "序录 · 四气五味", "s": "药有酸咸甘苦辛五味，又有寒热温凉四气，及有毒无毒，阴干曝干，采造时月生熟，土地所出，真伪陈新，并各有法。", "tr": "药物有酸、咸、甘、苦、辛五味，又有寒、热、温、凉四气，还有有毒无毒之别；阴干还是晒干、采收炮制的时月、生用熟用、产地、真伪与新陈，都各有法度，不可不察。"}, {"t": "序录 · 用药法度", "s": "疗寒以热药，疗热以寒药，饮食不消以吐下药，鬼疰蛊毒以毒药，痈肿疮瘤以疮药，风湿以风湿药，各随其所宜。", "tr": "治寒证用温热药，治热证用寒凉药，饮食积滞用涌吐泻下药，疫疠蛊毒用以毒攻毒之药，痈肿疮瘤用外科疮药，风湿用祛风湿药——各有对应，须随证择宜。"}], "伤寒论": [{"t": "太阳病篇 · 桂枝汤证", "s": "太阳中风，阳浮而阴弱。阳浮者热自发，阴弱者汗自出。啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣干呕者，桂枝汤主之。", "tr": "太阳中风证，脉象浮取有余、沉取不足。浮主发热自起，弱主汗液自出。病人阵阵怕冷、如遇凉水般恶风、周身发热，兼有鼻塞作响、干呕的，用桂枝汤主治。"}, {"t": "太阳病篇 · 辨证总纲", "s": "太阳之为病，脉浮，头项强痛而恶寒。", "tr": "太阳病的基本证候是：脉浮，头项部僵硬疼痛，并且怕冷。这一条是六经辨证的第一提纲。"}, {"t": "阳明病篇 · 白虎汤证", "s": "伤寒脉浮滑，此表有热、里有寒，白虎汤主之。（按：历代注家于「里有寒」多作「里有热」解，读时宜参诸家注本。）", "tr": "外感病见脉浮而滑，是表有热、里亦有热的证候，用白虎汤主治。此条文字历代注家争议颇多，阅读时宜对照不同注本，不必强作定论。"}], "本草纲目": [{"t": "序例 · 释名举例", "s": "药有数名者，或因形，或因色，或因气，或因味，或因时，或因地产，或因功用，不可不察也。", "tr": "一味药常有若干名称，有的取自形状，有的取自颜色，有的取自气味，有的取自采收时节，有的取自产地，有的取自功效——读本草时不可不逐一辨析。"}, {"t": "草部 · 人参条", "s": "参渐长成者，根如人形，有神，故谓之人参。", "tr": "人参长成之后，根形似人，古人认为颇有灵气，所以称作「人参」。李时珍于此条下详辨产地、真伪与炮制。"}, {"t": "水部 · 节气水", "s": "一年二十四节气，一节主半月，水之气味随之变迁，此乃天地之气候相感，又非疆域之限也。", "tr": "一年二十四节气，每节主半个月，水的气味随节气而变，这是天地气候相互感通所致，并不受地域界限的拘束。此说体现古人顺时取物之意，宜作文化知识看待。"}], "千金方": [{"t": "序 · 大医精诚（节）", "s": "凡大医治病，必当安神定志，无欲无求，先发大慈恻隐之心，誓愿普救含灵之苦。", "tr": "凡是良医治病，一定要安定心神、志意专一，没有私欲与求取，先发起大慈悲与恻隐之心，立誓普遍救度众生的疾苦。"}, {"t": "序 · 大医精诚（论医德）", "s": "若有疾厄来求救者，不得问其贵贱贫富，长幼妍媸，怨亲善友，华夷愚智，普同一等，皆如至亲之想。", "tr": "若有病患来求救治，不可以追问他地位高低、钱财多少、年纪长幼、相貌美丑，是怨家还是亲友，是本地人还是外乡人，是聪慧还是愚钝；一律平等看待，都当作至亲来想。"}, {"t": "养性 · 食治", "s": "夫为医者，当须先洞晓病源，知其所犯，以食治之；食疗不愈，然后命药。", "tr": "行医之人，必须先透彻弄清病源、明白病从何来，先用饮食调治；食疗不见效，然后才考虑用药。这是「药食同源、先食后药」的经典表述。"}], "温病条辨": [{"t": "上焦篇 · 银翘散", "s": "太阴风温、温热、温疫、冬温，初起恶寒者，桂枝汤主之；但热不恶寒而渴者，辛凉平剂银翘散主之。", "tr": "手太阴肺经的风温、温热、温疫、冬温，初起怕冷的用桂枝汤；只发热不怕冷且口渴的，用辛凉平剂银翘散主治。此条可见温病与伤寒治法之别。"}, {"t": "上焦篇 · 桑菊饮", "s": "太阴风温，但咳，身不甚热，微渴者，辛凉轻剂桑菊饮主之。", "tr": "手太阴风温，只有咳嗽、身热不重、微微口渴的，用辛凉轻剂桑菊饮主治。银翘散为平剂、桑菊饮为轻剂，轻重有别。"}, {"t": "杂说 · 治病法论", "s": "治上焦如羽，非轻不举；治中焦如衡，非平不安；治下焦如权，非重不沉。", "tr": "治上焦病要像羽毛一样轻清，药不轻灵就升举不起来；治中焦病要像秤杆一样持平，不平就不得安和；治下焦病要像秤砣一样重坠，不重就沉不下去。"}], "汤头歌诀": [{"t": "补益之剂 · 四君子汤", "s": "四君子汤中和义，参术茯苓甘草比。益气健脾基础剂，脾胃气虚治相宜。", "tr": "四君子汤取「君子致中和」之义，由人参、白术、茯苓、甘草配伍而成，是益气健脾的基础方，脾胃气虚之证最为相宜。"}, {"t": "解表之剂 · 桂枝汤", "s": "桂枝汤治太阳风，芍药甘草姜枣同。解肌发表调营卫，表虚有汗此为功。", "tr": "桂枝汤主治太阳中风，配伍芍药、甘草、生姜、大枣。功能解肌发表、调和营卫，专为表虚有汗之证而设。"}, {"t": "清热之剂 · 白虎汤", "s": "白虎汤用石膏偎，知母甘草粳米陪。亦有加入人参者，燥烦热渴舌生苔。", "tr": "白虎汤以石膏为主，配知母、甘草、粳米。也有加人参的变法，适用于燥烦、大热大渴、舌上生苔之证。"}], "随息居饮食谱": [{"t": "谷食类 · 绿豆", "s": "绿豆甘凉，煮食清胆养胃，解暑止渴，润皮肤，消浮肿，利小便；非暑热者勿多食。", "tr": "绿豆味甘性凉，煮食可清胆养胃、解暑止渴、润泽皮肤、消浮肿、利小便；不属暑热证的人不宜多吃。"}, {"t": "蔬食类 · 山药", "s": "山药甘平，煮食补脾肾，调二便，强筋骨，丰肌体，辟雾露清虚热。", "tr": "山药味甘性平，煮食能补脾益肾、调畅二便、强健筋骨、充实肌体，并能抵御雾露之邪、清解虚热。"}, {"t": "调和类 · 生姜", "s": "生姜辛温，散风寒，温中祛痰湿，止呕开胃，多食耗气损阴，阴虚内热者忌之。", "tr": "生姜味辛性温，能发散风寒、温中化痰湿、止呕开胃；但多吃会耗气伤阴，阴虚内热的人应当忌用。"}], "难经": [{"t": "一难 · 诊脉独取寸口", "s": "十二经皆有动脉，独取寸口，以决五脏六腑死生吉凶之法，何谓也？寸口者，脉之大会，手太阴之脉动也。", "tr": "十二经都有可触及的动脉，为何单取寸口来判断五脏六腑的死生吉凶？因为寸口是诸脉汇聚之处，是手太阴肺经的脉动所在。"}, {"t": "六十一难 · 望闻问切", "s": "望而知之谓之神，闻而知之谓之圣，问而知之谓之工，切脉而知之谓之巧。", "tr": "通过望诊就辨明病情的称为「神」，通过闻诊辨明的称为「圣」，通过问诊辨明的称为「工」，通过切脉辨明的称为「巧」。此即四诊并重的经典表述。"}, {"t": "七十七难 · 治未病", "s": "所谓治未病者，见肝之病，则知肝当传之与脾，故先实其脾气，无令得受肝之邪。", "tr": "所谓「治未病」，是说见到肝病，便知道肝病会传变到脾，因此先充实脾气，使脾不受肝邪侵袭。这与《内经》「上工治未病」一脉相承。"}], "肘后备急方": [{"t": "序 · 救急之意", "s": "余今采其要约，以为《肘后备急方》三卷，率多易得之药，其不获已须买之者，亦皆贱价草石，所在皆有。", "tr": "我如今撮取前代方书的精要，编成《肘后备急方》三卷，所用大多是容易取得的药材；实在需要购买的，也多是价廉的草木矿石，随处可得。此书以简便廉验为务。"}, {"t": "治卒中诸急方", "s": "令爪其病人人中，取醒。（按：此为古代急救法之记载，仅作文献了解，现代急症须立即呼叫急救并就医。）", "tr": "用指甲掐按病人的人中穴使其苏醒。这是古代急救方法的文献记载，仅供了解；现代遇急症应立即呼叫急救、送医处置，不可据此自行处理。"}, {"t": "治寒热诸疟方", "s": "青蒿一握，以水二升渍，绞取汁，尽服之。（按：此条为屠呦呦团队发现青蒿素之文献线索，读其文当明古今研究之别。）", "tr": "取青蒿一把，用两升水浸泡后绞取汁液，一次服尽。此条是青蒿素研究的著名文献线索；阅读时应明白古代经验记载与现代药物研究之间的区别。"}], "医学三字经": [{"t": "医学源流第一", "s": "医之始，本岐黄；灵枢作，素问详；难经出，更洋洋；越汉季，有南阳。", "tr": "医学的开端，本于岐伯与黄帝；《灵枢》成书、《素问》详备；《难经》问世，内容更为宏富；到了汉代末年，又有南阳张仲景。"}, {"t": "中风第二", "s": "人百病，首中风；骤然得，八方通；闭与脱，大不同；开邪闭，续命雄。", "tr": "人体诸多病证中，中风列于首位；起病骤然，各方皆可涉及；闭证与脱证治法大不相同；开泄邪闭，古方续命汤一类较为峻猛。此篇为旧时歌诀，宜作医学史知识阅读。"}, {"t": "虚痨第三", "s": "虚痨病，从何起；七情伤，上损是；归脾汤，二阳旨；下损由，房帏迩。", "tr": "虚劳病从何而起？七情内伤，多从上焦损起；归脾汤所治，本于「二阳之病发心脾」之旨；下焦之损，则多与房劳过度相关。"}], "饮膳正要": [{"t": "序 · 食疗为本", "s": "保养之道，莫若守中；守中则无过与不及之病。调顺四时，节慎饮食，起居有常，不妄作劳。", "tr": "养生之道，没有比守住中道更好的；守住中道，就不会有过与不及的毛病。顺应四时调和，饮食有节制有慎择，起居有规律，不过度操劳。"}, {"t": "卷一 · 四时所宜", "s": "春气温，宜食麦以凉之；夏气热，宜食菽以寒之；秋气燥，宜食麻以润其燥；冬气寒，宜食黍以热性治其寒。", "tr": "春天气候温，宜食麦类以凉润；夏天气候热，宜食豆类以清解；秋天气候燥，宜食麻类（芝麻）以润燥；冬天气候寒，宜食黍类以温性御寒。此为古人四时食宜之说，宜结合体质看待。"}, {"t": "卷二 · 服药食忌", "s": "凡服药，不可多食生蒜、胡荽、生葱，及诸果、诸滑滞之物。", "tr": "大凡服药期间，不宜多吃生蒜、香菜、生葱，以及各种果实与滑腻滞胃之物。此属古代服药宜忌记载，具体宜忌应遵医嘱。"}]};
const SEASON_HERB_REC={"春": [{"n": "薄荷", "fit": ["气郁质", "湿热质"], "why": "春阳升发，薄荷轻宣疏散，助肝气条达而不峻"}, {"n": "菊花", "fit": ["湿热质", "阴虚质"], "why": "春风易生头目风热，菊花清头明目、平肝而不燥"}, {"n": "枸杞子", "fit": ["阴虚质", "平和质"], "why": "春木旺而易耗肝阴，枸杞子平补肝肾、滋而不腻"}, {"n": "黄芪", "fit": ["气虚质", "特禀质"], "why": "春令腠理渐开，黄芪固表益气，易感人群尤宜"}, {"n": "山药", "fit": ["气虚质", "平和质"], "why": "春脾易困，山药平补脾肺，煮粥最宜"}, {"n": "玫瑰花", "fit": ["气郁质", "血瘀质"], "why": "春应肝，玫瑰花芳香疏肝、和血解郁"}, {"n": "柴胡", "fit": ["气郁质", "湿热质"], "why": "春气升发，柴胡疏肝解郁、条达气机（须医师处方）"}, {"n": "防风", "fit": ["特禀质", "气虚质"], "why": "春风多风邪，防风祛风固表，为易感者所宜"}], "夏": [{"n": "金银花", "fit": ["湿热质", "特禀质"], "why": "暑热夹湿，金银花清热解毒、轻宣不伤胃"}, {"n": "莲子", "fit": ["气虚质", "平和质"], "why": "长夏脾虚，莲子补脾养心、煮羹最宜"}, {"n": "茯苓", "fit": ["痰湿质", "气虚质"], "why": "夏湿困脾，茯苓利水健脾、药性平和"}, {"n": "薏苡仁", "fit": ["痰湿质", "湿热质"], "why": "长夏湿盛，薏苡仁渗湿健脾、煮粥代茶"}, {"n": "生姜", "fit": ["阳虚质", "痰湿质"], "why": "夏月贪凉易伤中阳，生姜温中和胃"}, {"n": "荷叶", "fit": ["痰湿质", "湿热质"], "why": "暑湿交蒸，荷叶清暑化湿、升发清阳"}, {"n": "白扁豆", "fit": ["痰湿质", "气虚质"], "why": "长夏吐泻多因脾湿，白扁豆健脾化湿和中"}, {"n": "藿香", "fit": ["痰湿质", "湿热质"], "why": "暑湿秽浊，藿香芳香化浊、和中止呕"}], "秋": [{"n": "麦冬", "fit": ["阴虚质", "平和质"], "why": "秋燥伤津，麦冬养阴润肺、生津止渴"}, {"n": "桔梗", "fit": ["痰湿质", "特禀质"], "why": "秋令肺气宜宣，桔梗宣肺利咽、载药上行"}, {"n": "五味子", "fit": ["气虚质", "阴虚质", "特禀质"], "why": "秋主收敛，五味子敛肺生津、益气固表"}, {"n": "陈皮", "fit": ["痰湿质", "气郁质"], "why": "秋燥易滞中，陈皮理气健脾、燥湿化痰"}, {"n": "甘草", "fit": ["气虚质", "平和质", "特禀质"], "why": "秋燥咽干，甘草润肺和中、调和诸药"}, {"n": "百合", "fit": ["阴虚质", "气郁质", "平和质"], "why": "秋燥伤肺阴，百合润肺清心、蒸食煮粥皆宜"}, {"n": "玉竹", "fit": ["阴虚质", "平和质"], "why": "秋燥宜甘润，玉竹养阴润燥而不腻膈"}, {"n": "乌梅", "fit": ["特禀质", "阴虚质"], "why": "秋燥口渴，乌梅酸甘化阴、生津敛肺"}], "冬": [{"n": "当归", "fit": ["血瘀质", "阳虚质", "阴虚质"], "why": "冬主闭藏，当归补血活血，入膳炖汤宜冬令"}, {"n": "肉桂", "fit": ["阳虚质", "血瘀质"], "why": "冬寒伤阳，肉桂温补肾阳、少量入膳即可"}, {"n": "干姜", "fit": ["阳虚质", "痰湿质"], "why": "冬令中寒，干姜温中散寒、暖脾胃"}, {"n": "人参", "fit": ["气虚质", "阳虚质"], "why": "冬宜补虚，人参大补元气，宜文火另煎"}, {"n": "熟地黄", "fit": ["阴虚质", "血瘀质"], "why": "冬主藏精，熟地黄滋阴补血、填补下焦"}, {"n": "益智仁", "fit": ["阳虚质", "痰湿质"], "why": "冬寒夜尿频，益智仁温脾暖肾、固气摄唾"}, {"n": "肉苁蓉", "fit": ["阳虚质", "气虚质"], "why": "冬令温补宜缓，肉苁蓉温而不燥、兼润肠"}, {"n": "菟丝子", "fit": ["阳虚质", "阴虚质", "平和质"], "why": "冬应肾，菟丝子平补肝肾、固精而不峻"}]};
