/* 不重复抽签：按数组内容特征为键维护洗牌袋，抽空一轮后再重洗——内联数组每次新建实例也能命中同一牌堆 */
const _bags=new Map();
function pick(a){
  const key=a.length+'|'+String(a[0]).slice(0,12)+'|'+String(a[a.length-1]).slice(0,12);
  let bag=_bags.get(key);
  if(!bag||!bag.length){
    bag=a.slice();
    for(let i=bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]];}
    _bags.set(key,bag);
  }
  return bag.pop();
}
